<template>
  <div>
    <div class="row items-center justify-between"><div><div class="text-subtitle1 text-weight-bold">Compliance</div><div class="text-caption text-grey-7">Flags, alertas e histórico interno do cliente.</div></div><q-btn flat dense size="sm" color="primary" icon="add_alert" label="Nova flag" no-caps @click="openCreate" /></div>
    <q-banner v-if="error" class="bg-red-1 text-negative q-mt-md">{{ error }}<template #action><q-btn flat color="negative" label="Tentar novamente" @click="load" /></template></q-banner><div v-if="loading" class="row justify-center q-pa-xl"><q-spinner color="primary" size="32px" /></div>
    <template v-else><div class="row q-col-gutter-md q-mt-sm"><div class="col-12 col-md-4"><q-banner rounded :class="cardClass"><div class="text-caption">Situação</div><div class="text-subtitle1 text-weight-bold">{{ card.status||card.riskLevel||'Sem flags pendentes' }}</div></q-banner></div><div class="col-12 col-md-4"><q-banner rounded class="bg-blue-1 text-primary"><div class="text-caption">Flags abertas</div><div class="text-h6">{{ card.openFlagsCount??openFlags.length }}</div></q-banner></div><div class="col-12 col-md-4"><q-banner rounded class="bg-orange-1 text-warning"><div class="text-caption">Alertas</div><div class="text-h6">{{ alerts.length }}</div></q-banner></div></div>
      <div class="text-weight-medium q-mt-lg q-mb-sm">Flags</div><q-table flat dense hide-pagination row-key="id" :rows="flags" :columns="columns"><template #body-cell-severity="p"><q-td :props="p"><q-badge :color="severityColor(p.value)">{{ p.value }}</q-badge></q-td></template><template #body-cell-status="p"><q-td :props="p"><q-badge outline color="primary">{{ p.value }}</q-badge></q-td></template><template #body-cell-actions="p"><q-td :props="p"><row-actions :actions="actions(p.row)" @select="a=>runAction(a,p.row)" /></q-td></template><template #no-data><div class="full-width text-center text-grey-7 q-pa-lg">Nenhuma flag cadastrada.</div></template></q-table>
