    <q-dialog v-model="formDialog"><q-card class="form-dialog"><title-card :title="editingId?'Editar flag':'Nova flag de compliance'" @on-close="formDialog=false" /><q-card-section><q-form ref="formRef" @submit.prevent="save"><div class="row q-col-gutter-md"><label-form class-name="col-12 col-md-6" text-label="Tipo"><q-input v-model.trim="draft.flagType" outlined dense :disable="Boolean(editingId)" :rules="requiredRules" /></label-form><label-form class-name="col-12 col-md-6" text-label="Severidade"><q-select v-model="draft.severity" outlined dense emit-value map-options :options="severities" :rules="requiredRules" /></label-form><label-form v-if="!editingId" class-name="col-12" text-label="Título"><q-input v-model.trim="draft.title" outlined dense :rules="requiredRules" /></label-form><label-form class-name="col-12" text-label="Descrição"><q-input v-model.trim="draft.description" type="textarea" outlined dense /></label-form><label-form class-name="col-12 col-md-6" text-label="Status"><q-select v-model="draft.status" outlined dense emit-value map-options :options="statuses" /></label-form><label-form class-name="col-12 col-md-6" text-label="Frequência de monitoramento"><q-input v-model.trim="draft.monitoringFrequency" outlined dense /></label-form><label-form v-if="!editingId" class-name="col-12 col-md-6" text-label="Detectado por"><q-input v-model.trim="draft.detectedBy" outlined dense :rules="requiredRules" /></label-form><label-form v-if="!editingId" class-name="col-12 col-md-6" text-label="Detectado em"><q-input v-model="draft.detectedAtUtc" type="datetime-local" outlined dense /></label-form><label-form class-name="col-12 col-md-6" text-label="Relação PEP"><q-input v-model.trim="draft.relatedPepRelationship" outlined dense /></label-form><label-form class-name="col-12 col-md-6" text-label="Descrição PEP"><q-input v-model.trim="draft.relatedPepDescription" outlined dense /></label-form><label-form v-if="!editingId" class-name="col-12" text-label="Evidência"><q-input v-model.trim="draft.evidence" type="textarea" outlined dense /></label-form></div><div class="row justify-end q-mt-md"><q-btn type="submit" flat color="primary" icon="save" label="Salvar flag" no-caps :loading="saving" /></div></q-form></q-card-section></q-card></q-dialog>
    <q-dialog v-model="decisionDialog"><q-card class="form-dialog"><title-card :title="decision==='resolve'?'Resolver flag':'Descartar flag'" @on-close="decisionDialog=false" /><q-card-section><q-form @submit.prevent="saveDecision"><label-form text-label="Justificativa"><q-input v-model.trim="decisionDescription" type="textarea" outlined :rules="requiredRules" /></label-form><div class="row justify-end q-mt-md"><q-btn type="submit" flat :color="decision==='resolve'?'positive':'negative'" label="Confirmar" no-caps :loading="saving" /></div></q-form></q-card-section></q-card></q-dialog>
  </div>
</template>
<script setup>
import{computed,reactive,ref,watch}from'vue';import TitleCard from'src/components/Card/TitleCard.vue';import LabelForm from'src/components/Form/LabelForm.vue';import RowActions from'src/components/Entity/RowActions.vue';import useNotification from'src/composables/global/useNotification';import{getApiErrorMessage}from'src/services/apiError';import{createComplianceFlag,dismissComplianceFlag,getComplianceAlerts,getComplianceCard,getComplianceHistory,listComplianceFlags,resolveComplianceFlag,updateComplianceFlag}from'src/services/complianceService'
const props=defineProps({customerId:{type:String,required:true}}),emit=defineEmits(['updated']),{successNotify,errorNotify}=useNotification(),loading=ref(true),saving=ref(false),error=ref(''),card=ref({}),flags=ref([]),alerts=ref([]),history=ref([]),formDialog=ref(false),decisionDialog=ref(false),formRef=ref(null),editingId=ref(null),target=ref(null),decision=ref('resolve'),decisionDescription=ref('');const empty=()=>({flagType:'',severity:'Medium',status:'Open',title:'',description:'',monitoringFrequency:'',detectedBy:'Manual',detectedAtUtc:'',relatedPepDescription:'',relatedPepRelationship:'',evidence:''}),draft=reactive(empty()),collection=v=>Array.isArray(v)?v:v?.data||v?.items||[]
const columns=[{name:'title',label:'Flag',field:r=>r.title||r.flagType,align:'left'},{name:'severity',label:'Severidade',field:'severity',align:'left'},{name:'status',label:'Status',field:'status',align:'left'},{name:'actions',label:'',field:'id',align:'right'}],severities=['Low','Medium','High','Critical'].map(v=>({label:v,value:v})),statuses=['Open','Monitoring','Resolved','Dismissed'].map(v=>({label:v,value:v})),requiredRules=[v=>Boolean(String(v||'').trim())||'Campo obrigatório'],openFlags=computed(()=>flags.value.filter(f=>!['Resolved','Dismissed'].includes(f.status))),cardClass=computed(()=>openFlags.value.length?'bg-red-1 text-negative':'bg-green-1 text-positive')
const load=async()=>{loading.value=true;error.value='';const names=['card','flags','alertas','histórico'];const results=await Promise.allSettled([getComplianceCard(props.customerId),listComplianceFlags(props.customerId,{page:1,pageSize:100}),getComplianceAlerts(props.customerId),getComplianceHistory(props.customerId,{page:1,pageSize:100})]);if(results[0].status==='fulfilled')card.value=results[0].value||{};if(results[1].status==='fulfilled')flags.value=collection(results[1].value);if(results[2].status==='fulfilled')alerts.value=collection(results[2].value);if(results[3].status==='fulfilled')history.value=collection(results[3].value);const failed=results.map((r,i)=>r.status==='rejected'?names[i]:null).filter(Boolean);if(failed.length)error.value=`Não foi possível carregar: ${failed.join(', ')}.`;loading.value=false},actions=f=>[{name:'edit',label:'Editar',icon:'edit'},...(!['Resolved','Dismissed'].includes(f.status)?[{name:'resolve',label:'Resolver',icon:'check_circle',color:'positive'},{name:'dismiss',label:'Descartar',icon:'cancel',color:'negative'}]:[])],openCreate=()=>{editingId.value=null;Object.assign(draft,empty());formDialog.value=true}
const runAction=(a,f)=>{target.value=f;if(a==='edit'){editingId.value=f.id;Object.assign(draft,{...empty(),...f});formDialog.value=true;return}decision.value=a;decisionDescription.value='';decisionDialog.value=true},save=async()=>{if(!await formRef.value.validate())return;saving.value=true;try{if(editingId.value)await updateComplianceFlag(props.customerId,editingId.value,{severity:draft.severity,status:draft.status,description:draft.description||null,monitoringFrequency:draft.monitoringFrequency||null,relatedPepDescription:draft.relatedPepDescription||null,relatedPepRelationship:draft.relatedPepRelationship||null});else await createComplianceFlag(props.customerId,{...draft,detectedAtUtc:draft.detectedAtUtc?new Date(draft.detectedAtUtc).toISOString():null,description:draft.description||null,monitoringFrequency:draft.monitoringFrequency||null,relatedPepDescription:draft.relatedPepDescription||null,relatedPepRelationship:draft.relatedPepRelationship||null,evidence:draft.evidence||null});successNotify('Flag salva.');formDialog.value=false;await refresh()}catch(e){errorNotify(getApiErrorMessage(e,'Não foi possível salvar a flag.'))}finally{saving.value=false}},saveDecision=async()=>{saving.value=true;try{const fn=decision.value==='resolve'?resolveComplianceFlag:dismissComplianceFlag;await fn(props.customerId,target.value.id,decisionDescription.value||null);successNotify(decision.value==='resolve'?'Flag resolvida.':'Flag descartada.');decisionDialog.value=false;await refresh()}catch(e){errorNotify(getApiErrorMessage(e,'Não foi possível concluir a ação.'))}finally{saving.value=false}},refresh=async()=>{await load();emit('updated')},severityColor=s=>({Low:'grey',Medium:'warning',High:'orange',Critical:'negative'}[s]||'grey'),formatDate=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';watch(()=>props.customerId,load,{immediate:true})
</script><style scoped>.form-dialog{width:min(720px,calc(100vw - 32px))}</style>
